package com.enerlution.ems.business;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.enerlution.ems.auth.AccessControl;
import com.enerlution.ems.common.BusinessException;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
class StationDashboardHistoryExtrasTest {
 @Test void rejectsUnlistedOrEmptyFields(){assertThrows(BusinessException.class,()->StationDashboardHistoryExtras.fields("solar",List.of("password")));assertThrows(BusinessException.class,()->StationDashboardHistoryExtras.fields("solar",List.of()));assertThrows(BusinessException.class,()->StationDashboardHistoryExtras.fields("solar",java.util.Arrays.asList((String)null)));assertEquals(List.of("generationPower"),StationDashboardHistoryExtras.fields("solar",List.of("generationPower")));}
 @Test void workbookUsesSelectedFieldsTimezoneUnitsAndEmptyCells()throws Exception{var p=new ObjectMapper().readTree("{\"stationStatisticPowerList\":[{\"dateTime\":1792281600,\"batteryPower\":0},{\"dateTime\":1792281660,\"batteryPower\":1500}]}");var view=new StationHistoryService.View(true,"day","2026-10-18","Asia/Shanghai","database-mock","2026-10-18T00:00:00Z",p);var rows=StationDashboardHistoryExtras.rows(view,List.of("batteryPower","batterySoc"));assertTrue(rows.get(0).get(0).contains("Asia/Shanghai"));assertEquals("0",rows.get(1).get(1));assertEquals("",rows.get(1).get(2));assertEquals("1.5",rows.get(2).get(1));assertTrue(rows.get(1).get(0).contains("08:00"));}
 @Test void deniedExportAndTemplateSaveCannotQuery(){var db=mock(JdbcTemplate.class);var access=mock(AccessControl.class);doThrow(new BusinessException(403,"denied")).when(access).requireStationPermission(21,"report.export");doThrow(new BusinessException(403,"denied")).when(access).requireStationPermission(21,"asset.edit");var s=new DomainSupport(db,access);var e=new StationDashboardHistoryExtras(s,new StationHistoryService(s));assertThrows(BusinessException.class,()->e.workbook(21,"day","2026-10-18","overall",List.of("batteryPower")));assertThrows(BusinessException.class,()->e.save(21,new StationDashboardHistoryExtras.TemplateInput("a","overall",List.of("batteryPower"))));verifyNoInteractions(db);}
 @Test void aggregateExportsUseRequestedPeriodRowsAndOnlySelectedFields()throws Exception{var p=new ObjectMapper().readTree("{\"stationStatisticDayDtoList\":[{\"day\":1,\"generationValue\":0,\"gridValue\":1000}],\"stationStatisticYearDtoList\":[{\"year\":2026,\"generationValue\":2300}]}");var month=new StationHistoryService.View(true,"month","2026-10","UTC","database-mock","2026-10-18T00:00:00Z",p);assertEquals(List.of("1","0"),StationDashboardHistoryExtras.rows(month,List.of("generationValue")).get(1));var total=new StationHistoryService.View(true,"total","2026:2026","UTC","database-mock","2026-10-18T00:00:00Z",p);assertEquals(List.of("2026","2.3"),StationDashboardHistoryExtras.rows(total,List.of("generationValue")).get(1));}
 @Test void workbookIsActualXlsxWithLiteralCells()throws Exception{byte[] bytes=DeviceHistoryWorkbook.write("场站历史",List.of(List.of("=1+1","<missing>")));var entries=new HashMap<String,String>();try(var zip=new java.util.zip.ZipInputStream(new java.io.ByteArrayInputStream(bytes))){for(var e=zip.getNextEntry();e!=null;e=zip.getNextEntry())entries.put(e.getName(),new String(zip.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8));}assertTrue(entries.containsKey("xl/workbook.xml"));var sheet=entries.get("xl/worksheets/sheet1.xml");assertTrue(sheet.contains("t=\"inlineStr\""));assertTrue(sheet.contains("=1+1"));assertTrue(sheet.contains("&lt;missing&gt;"));assertFalse(sheet.contains("<f>"));}
 @Test void exportRechecksAllPermissionsAfterWorkbookGeneration()throws Exception{var db=mock(JdbcTemplate.class);var a=mock(AccessControl.class);var h=mock(StationHistoryService.class);when(h.read(21,"month","2026-10")).thenReturn(new StationHistoryService.View(true,"month","2026-10","UTC","database-mock","2026-10-18T00:00:00Z",new ObjectMapper().readTree("{}")));doNothing().doThrow(new BusinessException(403,"revoked")).when(a).requireStationPermission(21,"telemetry.read");assertThrows(BusinessException.class,()->new StationDashboardHistoryExtras(new DomainSupport(db,a),h).workbook(21,"month","2026-10","solar",List.of("generationValue")));verify(a,times(2)).requireStationPermission(21,"asset.read");}
 @Test void templateReadsAreScopedToStationActorAndScene(){var db=mock(JdbcTemplate.class);var a=mock(AccessControl.class);when(a.userId()).thenReturn(7L);var h=new StationHistoryService(new DomainSupport(db,a));assertTrue(new StationDashboardHistoryExtras(new DomainSupport(db,a),h).templates(21,"solar").isEmpty());verify(db).queryForList(org.mockito.ArgumentMatchers.contains("station_id=? AND actor_id=? AND scene=?"),org.mockito.ArgumentMatchers.eq(21L),org.mockito.ArgumentMatchers.eq(7L),org.mockito.ArgumentMatchers.eq("solar"));} @Test void gridWorkbookPreservesAlreadyScaledUnitsAndFiltersDate()throws Exception{var p=new ObjectMapper().readTree("{\"dashboardSupplement\":{\"timezone\":\"Asia/Shanghai\",\"grid\":{\"history\":{\"day\":[{\"date\":\"1792281600\",\"activeKw\":1.5,\"powerFactor\":0},{\"date\":\"1792195200\",\"activeKw\":99}]}}}}");var v=new StationHistoryService.View(true,"day","2026-10-18","UTC","database-mock","2026-10-18T00:00:00Z",p);assertEquals(List.of("activeKw","powerFactor"),StationDashboardHistoryExtras.fields("grid",List.of("activeKw","powerFactor")));var rows=StationDashboardHistoryExtras.rows(v,List.of("activeKw","powerFactor"));assertEquals(2,rows.size());assertEquals("1.5",rows.get(1).get(1));assertEquals("0",rows.get(1).get(2));assertTrue(rows.get(1).get(0).contains("08:00"));} @Test void gridAggregateFallbackMatchesPeriodCoordinatesAndExplicitFactor()throws Exception{var p=new ObjectMapper().readTree("{\"stationStatisticDayDtoList\":[{\"acceptDay\":\"20261001\",\"buyValue\":1200,\"powerFactor\":0},{\"day\":32,\"buyValue\":9900},{\"acceptDay\":\"20260901\",\"buyValue\":9900},{\"day\":1,\"buyValue\":0}]}");var view=new StationHistoryService.View(true,"month","2026-10","UTC","database-mock","2026-10-18T00:00:00Z",p);var rows=StationDashboardHistoryExtras.rows(view,List.of("buyKwh","powerFactor","positiveReactiveKvarh"));assertEquals(3,rows.size());assertEquals(List.of("2026-10-01","1.2","0",""),rows.get(1));assertEquals(List.of("2026-10-01","0","",""),rows.get(2));} @Test void acceptedMpptAndStorageLoadParametersRemainExportable()throws Exception{assertEquals(List.of("usePower","mpptGenerationPower","batteryDcPower"),StationDashboardHistoryExtras.fields("storage",List.of("usePower","mpptGenerationPower","batteryDcPower")));assertEquals(List.of("mpptGenerationValue"),StationDashboardHistoryExtras.fields("solar",List.of("mpptGenerationValue")));var p=new ObjectMapper().readTree("{\"stationStatisticPowerList\":[{\"dateTime\":1792281600,\"mpptGenerationPower\":1500,\"usePower\":0,\"batteryDcPower\":-1000}]}");var v=new StationHistoryService.View(true,"day","2026-10-18","UTC","reference-capture","2026-10-18T00:00:00Z",p);assertEquals(List.of("2026-10-18T00:00:00Z","1.5","0","-1"),StationDashboardHistoryExtras.rows(v,List.of("mpptGenerationPower","usePower","batteryDcPower")).get(1));} @Test void weatherIsAnOptionalLiteralTextColumn()throws Exception{assertEquals(List.of("weather"),StationDashboardHistoryExtras.fields("solar",List.of("weather")));var p=new ObjectMapper().readTree("{\"stationStatisticPowerList\":[{\"dateTime\":1792281600,\"weather\":\"=SUN()\"},{\"dateTime\":1792281660}]}");var v=new StationHistoryService.View(true,"day","2026-10-18","UTC","reference-capture","2026-10-18T00:00:00Z",p);var rows=StationDashboardHistoryExtras.rows(v,List.of("weather"));assertEquals("=SUN()",rows.get(1).get(1));assertEquals("",rows.get(2).get(1));}}






